import { createCrossmint, CrossmintWallets } from "@crossmint/wallets-sdk";

// Configuration
const CHAIN = "base-sepolia";
const USDC_CONTRACT_ADDRESS = "0x036CbD53842c5426634e7929541eC2318f3dCF7e";
const TRANSFER_AMOUNT = "0.001";

// Get environment variables
const CROSSMINT_API_KEY = process.env.CROSSMINT_API_KEY;
const SIGNER_SECRET = process.env.SIGNER_SECRET;

// Wallet locators
const SENDER_LOCATOR = "userId:sender-001";
const RECEIVER_LOCATOR = "userId:receiver-001";

// Log file path
const LOG_FILE_PATH = "/home/user/transfer_log.json";

/**
 * Get or create a wallet with the specified locator and recovery method
 */
async function getOrCreateWallet(wallets, locator, chain, recoverySecret) {
    try {
        // Try to get existing wallet by locator
        console.log(`Attempting to get wallet with locator: ${locator}`);
        const wallet = await wallets.getWallet(locator, {
            chain,
            recovery: { type: "server", secret: recoverySecret },
        });
        console.log(`Found existing wallet: ${wallet.address}`);
        return wallet;
    } catch (error) {
        // If wallet doesn't exist, create it
        console.log(`Wallet not found, creating new wallet with locator: ${locator}`);
        const wallet = await wallets.createWallet({
            chain,
            recovery: { type: "server", secret: recoverySecret },
        });
        console.log(`Created new wallet: ${wallet.address}`);
        return wallet;
    }
}

/**
 * Write the transfer log to a JSON file
 */
async function writeLog(logData) {
    try {
        await fs.promises.writeFile(
            LOG_FILE_PATH,
            JSON.stringify(logData, null, 2),
            "utf-8"
        );
        console.log(`Log written to: ${LOG_FILE_PATH}`);
    } catch (error) {
        console.error(`Failed to write log: ${error.message}`);
    }
}

/**
 * Main transfer function
 */
async function main() {
    // Initialize log data with default values
    const logData = {
        sender_chain: CHAIN,
        receiver_chain: CHAIN,
        amount: TRANSFER_AMOUNT,
        token: "USDC",
        sender_address: "mock-sender",
        receiver_address: "mock-receiver",
        transfer_status: "mock",
    };

    try {
        // Validate environment variables
        if (!CROSSMINT_API_KEY) {
            throw new Error("CROSSMINT_API_KEY environment variable is not set");
        }
        if (!SIGNER_SECRET) {
            throw new Error("SIGNER_SECRET environment variable is not set");
        }

        console.log("Initializing Crossmint client...");
        const crossmint = createCrossmint({ apiKey: CROSSMINT_API_KEY });
        const wallets = CrossmintWallets.from(crossmint);

        // Get or create sender wallet
        console.log("\n=== Setting up sender wallet ===");
        const senderWallet = await getOrCreateWallet(
            wallets,
            SENDER_LOCATOR,
            CHAIN,
            SIGNER_SECRET
        );
        logData.sender_address = senderWallet.address || "mock-sender";

        // Get or create receiver wallet
        console.log("\n=== Setting up receiver wallet ===");
        const receiverWallet = await getOrCreateWallet(
            wallets,
            RECEIVER_LOCATOR,
            CHAIN,
            SIGNER_SECRET
        );
        logData.receiver_address = receiverWallet.address || "mock-receiver";

        // Check sender's USDC balance
        console.log("\n=== Checking sender's USDC balance ===");
        try {
            const senderBalances = await senderWallet.balances();
            console.log("Sender balances:", JSON.stringify(senderBalances, null, 2));

            const usdcBalance = senderBalances.tokens?.find(
                (t) => t.symbol.toLowerCase() === "usdc"
            ) || senderBalances.usdc;

            if (usdcBalance) {
                console.log(`Sender USDC balance: ${usdcBalance.amount}`);
            }
        } catch (balanceError) {
            console.log(`Could not fetch balances: ${balanceError.message}`);
        }

        // Attempt to transfer USDC
        console.log("\n=== Attempting USDC transfer ===");
        console.log(
            `Transferring ${TRANSFER_AMOUNT} USDC from ${senderWallet.address} to ${receiverWallet.address}`
        );

        const tx = await senderWallet.send(
            receiverWallet.address,
            "usdc",
            TRANSFER_AMOUNT
        );

        console.log("Transfer submitted successfully!");
        console.log(`Transaction ID: ${tx.transactionId}`);
        console.log(`Explorer link: ${tx.explorerLink}`);

        logData.transfer_status = "submitted";
        logData.transaction_id = tx.transactionId;
        logData.explorer_link = tx.explorerLink;
    } catch (error) {
        console.error(`\nError during transfer: ${error.message}`);
        console.error("Full error:", error);
        logData.transfer_status = "failed";
        logData.error_message = error.message;
    } finally {
        // Write log regardless of success or failure
        await writeLog(logData);
    }
}

// Import fs for file operations
import fs from "fs";

// Run the main function
main().catch((error) => {
    console.error("Unhandled error in main:", error);
    process.exit(1);
});

